files.content:
:root {
  --bg: #1a1c2c;
  --panel: #29366f;
  --border: #fff1e8;
  --text: #fff1e8;
  --accent: #ff004d;
  --input-bg: #0f1022;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: monospace;
  color: var(--text);
  image-rendering: pixelated;
}

.converter {
  background: var(--panel);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #000;
  padding: 28px;
  width: min(360px, 90vw);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

h1 {
  margin: 0;
  font-size: 28px;
  text-align: center;
  letter-spacing: 2px;
  text-shadow: 3px 3px #000;
}

.formula {
  margin: 0;
  background: var(--input-bg);
  border: 2px solid var(--border);
  padding: 8px;
  font-size: 12px;
  line-height: 1.5;
  text-align: center;
}

label {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

input,
select,
output,
button {
  width: 100%;
  font-family: inherit;
  font-size: 16px;
  border: 3px solid var(--border);
  background: var(--input-bg);
  color: var(--text);
  padding: 10px;
  outline: none;
}

input:focus-visible,
select:focus-visible,
button:focus-visible,
output:focus-visible {
  outline: 3px dashed var(--accent);
  outline-offset: 3px;
}

button {
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font-weight: bold;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 #000;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

output {
  display: block;
  text-align: center;
  font-size: 24px;
  min-height: 52px;
  font-weight: bold;
}

const tempInput = document.getElementById('temperature');
const direction = document.getElementById('direction');
const convertBtn = document.getElementById('convert');
const result = document.getElementById('result');

function convertTemperature(raw, selectedDirection) {
  if (raw.trim() === '') return 'Error';
  const value = Number(raw);
  if (!Number.isFinite(value)) return 'Error';
  const converted = selectedDirection === 'c-to-f'
    ? (value * 9) / 5 + 32
    : ((value - 32) * 5) / 9;
  return converted.toFixed(2);
}

convertBtn.addEventListener('click', () => {
  result.textContent = convertTemperature(tempInput.value, direction.value);
});

[tempInput, direction].forEach((element) => {
  element.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      convertBtn.click();
    }
  });
});
